SELECT * FROM dbo.Shippers;
SELECT o.OrderID
FROM dbo.Orders o
WHERE o.ShipperID IN (
    SELECT s.| FROM dbo.Shippers s
)

EXEC dbo.usp_GetCustomerOrders @CustomerID = 1;
SELECT 1;
